--
-- Name: sentry_notificationmessage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sentry_notificationmessage (
    id bigint NOT NULL,
    error_details text,
    error_code integer,
    message_identifier text,
    rule_action_uuid text,
    date_added timestamp with time zone NOT NULL,
    open_period_start timestamp with time zone,
    group_id bigint,
    incident_id bigint,
    parent_notification_message_id bigint,
    trigger_action_id bigint,
    rule_fire_history_id bigint,
    action_id bigint,
    CONSTRAINT notification_type_mutual_exclusivity CHECK ((((incident_id IS NOT NULL) AND (trigger_action_id IS NOT NULL) AND (rule_action_uuid IS NULL) AND (rule_fire_history_id IS NULL) AND (action_id IS NULL) AND (group_id IS NULL) AND (open_period_start IS NULL)) OR ((incident_id IS NULL) AND (trigger_action_id IS NULL) AND (rule_action_uuid IS NOT NULL) AND (rule_fire_history_id IS NOT NULL) AND (action_id IS NULL) AND (group_id IS NULL)) OR ((incident_id IS NULL) AND (trigger_action_id IS NULL) AND (rule_action_uuid IS NULL) AND (rule_fire_history_id IS NULL) AND (action_id IS NOT NULL) AND (group_id IS NOT NULL))))
);


